using HabitFlow.Application; using HabitFlow.Domain; using Xunit;
public class CoreRulesTests{[Fact]public void Calculates_current_and_best_streak(){var svc=new ProgressService(); var today=new DateOnly(2026,6,26); var dates=new[]{today,today.AddDays(-1),today.AddDays(-3)}; Assert.Equal(2,svc.CurrentStreak(dates,today)); Assert.Equal(2,svc.BestStreak(dates));}[Fact]public void Enforces_free_plan_limit(){var user=new User(Guid.NewGuid(),"A","a@b.com","hash","User","Active","Free","Active",false,false,null,null,null,DateTime.UtcNow,DateTime.UtcNow); Assert.False(new HabitPolicy().CanCreate(user,5).Succeeded);}[Fact]public void Sanitizes_sensitive_log_values(){Assert.DoesNotContain("abc",new LogSanitizer().Sanitize("token=abc password=abc"));}[Fact]public void Generates_protocol(){Assert.StartsWith("HF-",new ProtocolGenerator().Generate());}[Theory][InlineData("+5511999999999",true)][InlineData("abc",false)]public void Validates_whatsapp(string n,bool expected){Assert.Equal(expected,new WhatsAppValidator().IsValid(n));}[Fact]public void Hashes_password(){var h=new BCryptPasswordHasher(); var hash=h.Hash("Password123!"); Assert.True(h.Verify("Password123!",hash));}}
